            "send_labels_are_assigned_in_the_classify": "Etichetele trimiterilor se atribuie în pasul Clasifică și sunt reținute per cont. Editează-le în masă într-un tabel, dacă preferi:",
            "say_what_each_outbound_send_was_so": "Spune ce a fost fiecare trimitere, ca să fie impozitată corect. Orice trimitere e tratată ca vânzare impozabilă dacă nu o etichetezi — marcarea propriului exchange, a propriilor portofele, a cadourilor sau donațiilor schimbă impozitul. Etichetele sunt reținute data viitoare. Continuă le aplică și recalculează raportul.",
