            "opening_balances_are_tokens_you_already_held": "Soldurile de deschidere sunt tokenuri pe care le dețineai deja înainte de prima operațiune înregistrată a acestui cont. Setează-le, ca înstrăinările mai vechi să aibă o bază de cost reală în loc de un câștig cu cost zero (supraevaluat). Costul este totalul plătit pentru acea sumă de deschidere, în {{cur}}.",
            "generate_a_record_of_your_on_chain": "Generează o evidență a activității tale on-chain pe un interval de date, clasificată fiscal de motorul FairFlow. Completează opțiunile, clasifică-ți trimiterile, apoi exportă ca PDF, CSV sau JSON.",
