            "adding_a_password_provides_extra_security_especi": "Adăugarea unei parole oferă securitate suplimentară, mai ales pentru frazele seed mai scurte.",
            "you_are_about_to_request_a_change": "Ești pe cale să soliciți o schimbare a contului de recuperare pentru <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Nominalizează un cont de încredere — un cofondator, un portofel-soră pe care îl controlezi sau un contact pe care îl poți găsi pe altă cale — care să te ajute să recapeți accesul dacă îți pierzi vreodată cheia owner sau dacă e compromisă. Fluxul de recuperare folosește istoricul cheii tale owner, deci contul de recuperare singur nu îți poate confisca niciodată contul: te poate doar asista în recuperarea lui. Schimbările intră în vigoare după o fereastră de așteptare de 30 de zile.",
            "strong_30_day_waiting_period_strong_changing": "<strong>Perioadă de așteptare de 30 de zile.</strong> Schimbarea contului de recuperare nu e instantanee. O cerere nouă intră în vigoare la <strong>30 de zile după transmitere</strong>; până atunci, contul de recuperare curent rămâne valabil. O nouă transmitere în timpul ferestrei de așteptare înlocuiește cererea în curs. Setarea înapoi la valoarea curentă anulează o schimbare în așteptare.",
            "pick_someone_you_trust_personally_a_co": "Alege pe cineva în care ai încredere personal — un cofondator, un cont-soră pe care îl controlezi sau un portofel al cărui deținător poate fi contactat pe altă cale.",
            "generate_a_fresh_seed_phrase_to_derive": "Generează o frază seed nouă pentru a deriva chei noi pentru contul tău. Fraza seed este cheia-master a tuturor cheilor contului — păstreaz-o în siguranță și nu o împărtăși niciodată. Cheia owner va fi folosită pentru a semna tranzacția de actualizare a cheilor când confirmi mai jos.",
            "this_will_strong_cancel_any_pending_recovery": "Aceasta va <strong>anula orice schimbare în așteptare a contului de recuperare</strong> prin retransmiterea aceleiași valori ca a contului de recuperare curent. Cererea în curs, cu așteptare de 30 de zile, va fi înlocuită; contul de recuperare curent rămâne valabil pe tot parcursul.",
            "once_broadcast_the_chain_will_create_a": "Odată transmisă, lanțul va crea o cerere în așteptare care intră în vigoare în <strong>30 de zile</strong>. Contul tău de recuperare curent (<0>@{{currentRecovery}}</0>) rămâne valabil până atunci. Ți se va cere <strong>cheia owner</strong>.",
            "posting_description_1": "Această cheie ar trebui folosită pentru acțiuni de socializare, precum postare, comentare și vot. Are un set limitat de permisiuni și nu poate fi folosită pentru acțiuni monetare.",
            "posting_description_2": "Folosește această cheie pentru a te conecta la rețele sociale bazate pe Pixa, precum Pixagram.com. Păstreaz-o în siguranță.",
            "active_description_1": "Această cheie are permisiuni suplimentare pentru acțiuni monetare mai sensibile, precum transferul și schimbul de tokenuri.",
            "active_description_2": "Când efectuezi o acțiune legată de portofel, ți se poate cere autentificarea cu cheia Active. Introdu Active Key doar în aplicații în care ai încredere — oricine are acces la această cheie îți poate lua tokenurile.",
