            "some_figures_could_not_be_valued_in": "Unele cifre nu au putut fi evaluate în {{fiat}}: sursa de prețuri nu a returnat niciun curs {{fiat}} pentru ele. Sunt afișate ca „{{na}}” (nu zero), iar fiecare total care le include este incomplet. Corectează sursa de prețuri înainte de a folosi acest raport.",
